<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#222;font-size:12px}.head,.row{display:flex;justify-content:space-between}.box{border:1px solid #bbb;padding:14px;margin-top:18px}h1{font-size:20px}.amount{font-size:22px;font-weight:bold;text-align:center;margin:22px}.signature{margin-top:60px;text-align:right}</style></head><body>
<div class="head"><div><h1>{{ $school->trading_name }}</h1><div>{{ $school->address_line_1 }} {{ $school->city }}</div><div>{{ $school->phone }} · {{ $school->email }}</div></div><div><strong>REÇU DE PAIEMENT</strong><br>Nº {{ $payment->reference }}</div></div>
<div class="box"><div><strong>Étudiant :</strong> {{ $payment->student->full_name }}</div><div><strong>Formation :</strong> {{ $payment->enrollment->form?->course?->title ?? $payment->enrollment->trainingPlanGroup?->plan?->course?->title ?? 'Formation' }}</div><div><strong>Niveau / groupe :</strong> {{ $payment->enrollment->level ?: '—' }} / {{ $payment->enrollment->trainingPlanGroup?->name ?? ($payment->enrollment->group_number ? 'Groupe '.$payment->enrollment->group_number : '—') }}</div></div>
<div class="amount">{{ number_format(abs($payment->amount), 2, ',', ' ') }} {{ $currency }}</div>
<div class="box"><div><strong>Méthode :</strong> {{ $payment->payment_method->label() }}</div><div><strong>Date :</strong> {{ $payment->payment_date->format('d/m/Y') }}</div><div><strong>Solde précédent :</strong> {{ number_format($payment->previous_balance,2,',',' ') }} {{ $currency }}</div><div><strong>Solde restant :</strong> {{ number_format($payment->remaining_balance,2,',',' ') }} {{ $currency }}</div><div><strong>Caissier :</strong> {{ $payment->recorder?->name ?: 'Système' }}</div></div>
<div class="signature">Signature / cachet</div></body></html>
